export default class autoCompleteJS {
  constructor(config) {
    // Deconstructing config values
    const {
      name = "Search",
      selector = "#autoCompleteJS", // User input selector
      data: {
        src, // Data src selection
        key, // Data src key selection
        cache = true, // Flag to cache data src
      },
